using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

public class AddressableLoader : MonoBehaviour
{
    // Địa chỉ (address) của asset trong Addressables Group
    public AssetReference assetReference;

    void Start()
    {
        LoadAndInstantiateAsset();
    }

    private void LoadAndInstantiateAsset()
    {
        // Tải asset một cách bất đồng bộ
        assetReference.LoadAssetAsync<GameObject>().Completed += OnAssetLoaded;
    }

    private void OnAssetLoaded(AsyncOperationHandle<GameObject> handle)
    {
        if (handle.Status == AsyncOperationStatus.Succeeded)
        {
            // Tạo một instance của prefab đã tải
            Instantiate(handle.Result, transform.position, transform.rotation);
            Debug.Log("Asset loaded and instantiated successfully.");
        }
        else
        {
            Debug.LogError("Failed to load asset: " + handle.OperationException);
        }

        // Giải phóng handle khi đã dùng xong
        // Addressables.Release(handle);
        // Lưu ý: Nếu bạn chỉ instantiate, bạn có thể dùng assetReference.InstantiateAsync() 
        // để Addressables tự động quản lý việc giải phóng.
    }

    private void OnDestroy()
    {
      // Quan trọng: Giải phóng asset khi không cần dùng nữa
      // để tránh memory leak.
      assetReference.ReleaseAsset();
    }
}

